select count(*)
from t_r_data_perm_role_permission
where scope_code = #{scopeCode}

select from t_r_data_perm_role_permission p left join t_r_data_perm_scope sc on sc.code = p.scope_code where p.role_id = #{roleId}
and (p.catalog_name like concat('%', #{keyword}, '%') or p.database_name like concat('%', #{keyword}, '%') or p.table_name like concat('%', #{keyword}, '%') or p.column_name like concat('%', #{keyword}, '%'))
and p.scope_code in
#{code}
order by p.id

select 
from t_r_data_perm_role_permission
where id = #{id}
  and role_id = #{roleId}

mapper.update:
update t_r_data_perm_role_permission
set scope_code = #{entity.scopeCode},
    catalog_name        = #{entity.catalogName},
    database_name       = #{entity.databaseName},
    table_name          = #{entity.tableName},
    column_name         = #{entity.columnName},
    accesses            = #{entity.accesses}
where id = #{entity.id}
  and role_id = #{roleId}

mapper.delete:
delete from t_r_data_perm_role_permission
where id = #{id}
  and role_id = #{roleId}
